    const m = require('zigbee-herdsman-converters/lib/modernExtend');
    const exposes = require('zigbee-herdsman-converters/lib/exposes');
    const {exposeEndpoints} = require('zigbee-herdsman-converters/lib/utils');
    const e = exposes.presets;
    const ea = exposes.access;
    const {logger} = require('zigbee-herdsman-converters/lib/logger');

    // --- Déclaration du cluster custom ---
    function getMultiEventConfigCluster(endpointNames) {
      return m.deviceAddCustomCluster("multiEventConfig",{
        name: "multiEventConfig",
        ID: 0xfc10,
        manufacturerCode: 0x1141,
        endpointNames: endpointNames,
        attributes: {
          event_config:   {name: "event_config", ID: 0x0000, type: 0x41, write: true},
          backlight_mode: {name: "backlight_mode", ID: 0x0001, type: 0x30, write: true},
        },
        commands: {
          actionClick: {name: "click", ID: 0x00, parameters: [{name: "nbclicks", type: 0x30}]},
          actionHold: {name: "hold", ID: 0x01, parameters: [{name: "nbclicks", type: 0x30}]},
        },
        commandsResponse: {},
      });
    }

    const valueConverterArray16 = {
      to: (value) => {
        const params = JSON.parse(value);

        const list = [];
        for (const p of params) {
          list.push(
              {click: 0, hold: 1}[p.event],
              p.nbClicks,
              {onoff_toggle: 0, onoff_on: 1, onoff_off: 2, level_up: 3, level_down: 4}[p.command],
              p.dstAddress & 0xFF,
              (p.dstAddress >> 8) & 0xFF,
              p.dstEndpoint,
              p.extra[0],
              p.extra[1],
          );
        }
        return Buffer.from(list);
      },
      from: (value) => {
        const buf = Buffer.from(value, "hex");    
        cfg = [];
        for (let i = 0; i < buf.length; i += 8) {
          cfg.push({
            event: ["click","hold"][buf[i]],
            nbClicks: buf[i+1],
            command: ["onoff_toggle","onoff_on","onoff_off","level_up","level_down"][buf[i+2]],
            dstAddress: buf[i+3]|(buf[i+4] << 8),
            dstEndpoint: buf[i+5],
            extra: [buf[i+6],buf[i+7]],
          });
        }
        return JSON.stringify(cfg);
      },
    };

    // --- Extend custom modernExtend ---
    function multiEventConfigExtend(endpoints) {
      const endpointNames = Object.keys(endpoints);  
      
        return {
          isModernExtend: true,
          endpoints: endpointNames,
          exposes: [ 
            ...endpointNames.map((ep) => e.text("event_config", ea.ALL)
              .withEndpoint(ep)
              .withDescription("List of events settings like : event_type,nbclicks,cmd,address,endpoint,extra1,extra2"),
            ),
          ],
          fromZigbee: [
            {
              cluster: 'multiEventConfig',
              type: ['attributeReport', 'readResponse'],
              endpoint: (msg) => msg.endpoint.ID,
              convert: (model, msg, publish, options, meta) => {
                logger.error(`Received message for multiEventConfig: ${JSON.stringify(msg)}`);
                const ep = msg.endpoint.ID;

                // retrouver le nom correspondant à l'endpoint
                const name = endpointNames.find(k => endpoints[k] === ep);
                if (!name) return;
            
                if (msg.type === 'attributeReport' || msg.type === 'readResponse') {
                  const raw = msg.data.event_config;
                  //logger.warn(`Received raw event_config: ${raw}`);
                  if (!raw || raw.length === 0) return;
                
                  return {[`event_config_${name}`]: valueConverterArray16.from(msg.data.event_config)};
                }
              },
            },
            {
              cluster: 'multiEventConfig',
              type: ["commandActionClick", "commandActionHold"],
              endpoint: (msg) => msg.endpoint.ID,
              convert: (model, msg, publish, options, meta) => {
                logger.error(`Received message for multiEventConfig: ${JSON.stringify(msg)}`);
                const ep = msg.endpoint.ID;

                // retrouver le nom correspondant à l'endpoint
                const name = endpointNames.find(k => endpoints[k] === ep);
                if (!name) return;
                
                logger.error(`nbClicks = ${msg.data.nbclicks} or ${msg.data[0]} or ${JSON.stringify(msg.data)}`);
                switch(msg.type) {
                  case "commandActionClick":
                    return {action: `click_${name}_${String(msg.data.nbclicks)}`}
                    break;
                  case "commandActionHold":
                    return {action: `hold_${name}_${String(msg.data.nbclicks)}`}
                    break;
                }
              },
            },
          ], 
          toZigbee: [
            {
              key: ["event_config"],
              convertSet: async (entity, key, value, meta) => {
                //logger.error(`Setting ${key} to ${value} (raw: ${JSON.stringify(value)})`);
                const buf = valueConverterArray16.to(value);
                //const payload = {event_config: Buffer.concat([Buffer.from([buf.length]), buf])};
                const payload = {event_config: buf};
                            
                await entity.write(
                  'multiEventConfig',
                  payload,
                  {manufacturerCode: 0x1141},
                );

                return {[`event_config_${meta.endpoint_name}`]: value};
              },
              convertGet: async (entity, key, meta) => {
                //logger.error(`Getting ${key}`);
                await entity.read('multiEventConfig', ["event_config"],{manufacturerCode: 0x1141, endpoint: meta.endpoint})
              },
            },
          ],
          configure: [
            async (device, coordinatorEndpoint, logger) => {
              for (const epName in endpoints) {
                const epId = endpoints[epName];
                const endpoint = device.getEndpoint(epId);
                if (!endpoint) {
                  logger.error(`Endpoint ${epId} (${epName}) not found on device ${device.ieeeAddr}`);
                  continue;
                }
                await endpoint.read('multiEventConfig', ["event_config"],{manufacturerCode: 0x1141})
              }
            },
          ],
        };
    }

    function genExtend(endpoints) {
      let endpointNames = Object.keys(endpoints);
      let features = [
        m.deviceEndpoints({"endpoints": endpoints}), 
        m.onOff({"powerOnBehavior": true, "endpointNames": endpointNames}), 
        m.commandsOnOff({"endpointNames": endpointNames}), 
        m.commandsLevelCtrl({"endpointNames": endpointNames}),
        m.identify({"endpointNames": endpointNames}),
        getMultiEventConfigCluster(endpointNames),
        multiEventConfigExtend(endpoints),
      ];
      for (let i = 0; i < endpointNames.length; i++) {
        const epName = endpointNames[i];
        features.push(
          m.enumLookup({
            endpointName: epName,
            name: "switch_mode",
            lookup: {toggle: 0, momentary: 1, multifunction: 2},
            cluster: "genOnOffSwitchCfg",
            attribute: {ID: 0x4000, type: 0x30},
            description: "Switch Mode",
            entityCategory: "config",
          }),
          m.enumLookup({
            endpointName: epName,
            name: "switch_actions",
            lookup: {on_off: 0, off_on: 1, toggle: 2},
            cluster: "genOnOffSwitchCfg",
            attribute: "switchActions",
            description: "Actions switch",
            entityCategory: "config",
          }),
          m.enumLookup({
            endpointName: epName,
            name: "backlight_mode",
            lookup: {on: 0, off: 1, onoff: 2, offon: 3},
            cluster: "multiEventConfig",
            attribute: {ID: 0x0001, type: 0x30},
            description: "Backlight Mode",
            entityCategory: "config",
          }),
        );
      }
      
      return features;
    }


    // --- Module principal ---
    module.exports = [
      {
        zigbeeModel: ['ZS-EUB3'],
        model: 'ZS-EUB3',
        vendor: 'Moes',
        description: 'SmartSwitch 3-Gang',
        extend: genExtend({"left":1,"right":2,"center":3}),
        ota: true,
        icon: 'data:image/png;base64,',
      }
    ];
